      "expected": "STM32 VCAP pins require their specified capacitor connections and should not be routed to external UART connector pins.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"36\") (name \"NET0047\") (node (ref \"FCC2\") (pin \"48\") (pinfunction \"VCAP\") (pintype \"power_out\")) (node (ref \"UART3_FCC2\") (pin \"3\")"
        },
